-- Chave e local do clima ficam em secrets.lua, fora do git (veja
-- secrets.lua.example). Sem o arquivo, o clima só fica desligado.
local secrets = os.getenv("HOME") .. "/.config/hypr/secrets.lua"
local secretsFile = io.open(secrets, "r")
if secretsFile then
    secretsFile:close()
    dofile(secrets)
end
