------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "DP-1",
    mode     = "1920x1080@144",
    position = "0x0",
    scale    = "1",
    transform = 1,
})
hl.monitor({
    output   = "HDMI-A-1",
    disabled = true,
})
hl.monitor({
    output   = "DP-2",
    mode     = "1920x1080@144",
    position = "1080x420",
    scale    = "1",
})

-- Keep the primary workspaces on the landscape display and reserve the
-- persistent default workspace 10 for the portrait display.
for id = 1, 9 do
    hl.workspace_rule({ workspace = tostring(id), monitor = "DP-2" })
end
hl.workspace_rule({
    workspace = "10",
    monitor = "DP-1",
    default = true,
    persistent = true,
})
-- Reserved empty workspaces used while the Quickshell session lock is active.
hl.workspace_rule({ workspace = "98", monitor = "DP-1", persistent = true })
hl.workspace_rule({ workspace = "99", monitor = "DP-2", persistent = true })


